// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const rows = $('Get row(s) in sheet').all().map(item => item.json);

// Change these field names if your dataset uses different names.
const FIELD = {
  orderId: 'order_id',
  date: 'date',
  product: 'product',
  quantity: 'quantity',
  price: 'unit_price',
  discount: 'discount_pct',
  cost: 'unit_cost',
  category: 'category',
};

const now = new Date();
const DAY = 24 * 60 * 60 * 1000;

const currentStart = new Date(now.getTime() - 7 * DAY);
const previousStart = new Date(now.getTime() - 14 * DAY);

const money = n => Math.round(n * 100) / 100;

function number(value, fallback = 0) {
  if (value === null || value === undefined || value === '') {
    return fallback;
  }

  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

// Calculate discounted revenue and gross profit for each row.
const lines = rows.map(row => {
  const quantity = number(row[FIELD.quantity]);
  const price = number(row[FIELD.price]);
  const discount = number(row[FIELD.discount]);

  if (discount < 0 || discount > 100) {
    throw new Error('Discount must be between 0 and 100%.');
  }

  const revenue = quantity * price * (1 - discount / 100);

  const hasCost =
    row[FIELD.cost] !== null &&
    row[FIELD.cost] !== undefined &&
    row[FIELD.cost] !== '';

  const cost = hasCost
    ? quantity * number(row[FIELD.cost])
    : null;

  const date = new Date(row[FIELD.date]);

  return {
    ...row,
    _date: date,
    _revenue: revenue,
    _cost: cost,
    _profit: cost === null ? null : revenue - cost,
  };
});

// Keep the current and previous seven-day windows separate.
const current = lines.filter(row =>
  !isNaN(row._date.getTime()) &&
  row._date >= currentStart &&
  row._date <= now
);

const previous = lines.filter(row =>
  !isNaN(row._date.getTime()) &&
  row._date >= previousStart &&
  row._date < currentStart
);

function summarize(periodRows) {
  const revenue = periodRows.reduce(
    (sum, row) => sum + row._revenue, 0
  );

  const orderIds = new Set(
    periodRows
      .map(row => row[FIELD.orderId])
      .filter(id => id !== null && id !== undefined && id !== '')
      .map(String)
  );

  const knownCostRows = periodRows.filter(
    row => row._cost !== null
  );

  const cost = knownCostRows.reduce(
    (sum, row) => sum + row._cost, 0
  );

  const profit = knownCostRows.length
    ? knownCostRows.reduce((sum, row) => sum + row._profit, 0)
    : null;

  return {
    revenue: money(revenue),
    orders: orderIds.size,
    averageOrderValue: orderIds.size
      ? money(revenue / orderIds.size)
      : 0,
    costOfGoodsSold: knownCostRows.length
      ? money(cost)
      : null,
    grossProfit: profit === null ? null : money(profit),
    grossMarginPct: profit === null || revenue === 0
      ? null
      : money((profit / revenue) * 100),
    lineItems: periodRows.length,
    units: periodRows.reduce((sum, row) => sum + number(row[FIELD.quantity]), 0),
  };
}

const currentSummary = summarize(current);
const previousSummary = summarize(previous);

// Calculate percentage growth against the previous period.
const revenueChangePct = previousSummary.revenue !== 0
  ? money(
      ((currentSummary.revenue - previousSummary.revenue) /
        previousSummary.revenue) * 100
    )
  : null;

// Rank products by discounted revenue in the current period.
const products = {};

for (const row of current) {
  const name = row[FIELD.product] ?? 'Unknown product';

  if (!products[name]) {
    products[name] = { product: name, quantitySold: 0, revenue: 0 };
  }

  products[name].quantitySold += number(row[FIELD.quantity]);
  products[name].revenue += row._revenue;
}

const topProducts = Object.values(products)
  .map(product => ({
    ...product,
    revenue: money(product.revenue),
  }))
  .sort((a, b) => b.revenue - a.revenue)
  .slice(0, 5);

// Revenue per calendar day (this week vs the same weekday last week) for the charts in the email.
const dayKey = t => new Date(t).toISOString().slice(0, 10);
const todayMs = Date.parse(dayKey(now.getTime()));
const byDay = rowsArr => {
  const m = {};
  rowsArr.forEach(r => { const k = dayKey(r._date.getTime()); m[k] = (m[k] || 0) + r._revenue; });
  return m;
};
const curByDay = byDay(current);
const prevByDay = byDay(previous);
const dailyRevenue = [];
for (let i = 6; i >= 0; i--) {
  const ms = todayMs - i * DAY;
  dailyRevenue.push({
    date: dayKey(ms),
    revenue: money(curByDay[dayKey(ms)] || 0),
    previous: money(prevByDay[dayKey(ms - 7 * DAY)] || 0),
  });
}

// Revenue per category in the current period.
const cats = {};
for (const row of current) {
  const c = row[FIELD.category] || 'Uncategorised';
  cats[c] = (cats[c] || 0) + row._revenue;
}
const categories = Object.entries(cats)
  .map(([category, revenue]) => ({ category, revenue: money(revenue) }))
  .sort((a, b) => b.revenue - a.revenue)
  .slice(0, 6);

// Return one structured output item.
return [{
  json: {
    generatedAt: now.toISOString(),
    periods: {
      current: {
        start: currentStart.toISOString(),
        end: now.toISOString(),
        ...currentSummary,
      },
      previous: {
        start: previousStart.toISOString(),
        end: currentStart.toISOString(),
        ...previousSummary,
      },
    },
    revenueChangePct,
    topProducts,
    dailyRevenue,
    categories,
  },
}];

// Builds the email: charts and key figures are drawn here (not by the AI), and Gemini only adds the written analysis.
const d = $('Code in JavaScript').first().json;
const biz = $('Edit Fields').first().json;
const cur = d.periods.current, prev = d.periods.previous;
const currency = biz.currency || 'KES';
const AMBER = '#d97706';
const INK = '#0f172a', MUTED = '#64748b', RED = '#dc2626', GREEN = '#16a34a', BLUE = '#2563eb', GREY = '#cbd5e1', TEAL = '#0d9488', INDIGO = '#4f46e5';

const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = n => (n === null || n === undefined || isNaN(n)) ? '-' : Number(n).toLocaleString('en-US', { maximumFractionDigits: 0 });
const short = n => { n = Number(n) || 0; return n >= 1e6 ? (n / 1e6).toFixed(1) + 'M' : n >= 1e3 ? (n / 1e3).toFixed(1) + 'k' : String(Math.round(n)); };
const pct = n => (n === null || n === undefined) ? 'n/a' : (n > 0 ? '+' : '') + n + '%';
const chg = (a, b) => (b ? Math.round(((a - b) / b) * 1000) / 10 : null);
const colorOf = n => (n === null || n === undefined) ? MUTED : (n < 0 ? RED : GREEN);
const dayLabel = iso => new Date(iso + 'T00:00:00Z').toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', timeZone: 'UTC' });
const dateLabel = iso => new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });

// ---- key figures ----
const kpi = (label, value, sub, color) =>
  '<td width="25%" valign="top" style="padding:4px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px"><tr><td style="padding:10px 12px">' +
  '<div style="font-size:11px;color:' + MUTED + ';text-transform:uppercase">' + label + '</div>' +
  '<div style="font-size:18px;font-weight:bold;color:' + INK + ';padding:2px 0">' + value + '</div>' +
  '<div style="font-size:12px;color:' + color + '">' + sub + '</div></td></tr></table></td>';
const marginDiff = (cur.grossMarginPct != null && prev.grossMarginPct != null) ? Math.round((cur.grossMarginPct - prev.grossMarginPct) * 10) / 10 : null;
const ordersChg = chg(cur.orders, prev.orders), aovChg = chg(cur.averageOrderValue, prev.averageOrderValue);
const kpis = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>' +
  kpi('Revenue', currency + ' ' + fmt(cur.revenue), pct(d.revenueChangePct) + ' vs last week', colorOf(d.revenueChangePct)) +
  kpi('Orders', fmt(cur.orders), pct(ordersChg) + ' vs last week', colorOf(ordersChg)) +
  kpi('Avg order', currency + ' ' + fmt(cur.averageOrderValue), pct(aovChg) + ' vs last week', colorOf(aovChg)) +
  kpi('Gross margin', cur.grossMarginPct == null ? 'n/a' : cur.grossMarginPct + '%', marginDiff == null ? 'no cost data' : (marginDiff > 0 ? '+' : '') + marginDiff + ' pts vs last week', colorOf(marginDiff)) +
  '</tr></table>';

// ---- chart 1: revenue by day, this week vs last week ----
const days = d.dailyRevenue || [];
const maxV = Math.max(1, ...days.map(x => Math.max(x.revenue, x.previous)));
const barH = v => Math.max(2, Math.round((v / maxV) * 120));
const bar = (v, color) => '<td valign="bottom" style="padding:0 1px"><table role="presentation" cellpadding="0" cellspacing="0" width="14"><tr><td height="' + barH(v) + '" bgcolor="' + color + '" style="height:' + barH(v) + 'px;line-height:' + barH(v) + 'px;font-size:0">&nbsp;</td></tr></table></td>';
const dayChart = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr valign="bottom">' +
  days.map(x => '<td align="center" valign="bottom" width="14%"><div style="font-size:10px;color:' + MUTED + ';padding-bottom:2px">' + short(x.revenue) + '</div>' +
    '<table role="presentation" cellpadding="0" cellspacing="0" align="center"><tr valign="bottom">' + bar(x.previous, GREY) + bar(x.revenue, BLUE) + '</tr></table></td>').join('') +
  '</tr><tr>' + days.map(x => '<td align="center" style="font-size:11px;color:' + MUTED + ';padding-top:4px;border-top:1px solid #e2e8f0">' + dayLabel(x.date) + '</td>').join('') + '</tr></table>' +
  '<div style="font-size:12px;color:' + MUTED + ';padding-top:8px"><span style="color:' + GREY + '">&#9632;</span> Last week &nbsp; <span style="color:' + BLUE + '">&#9632;</span> This week</div>';

// ---- horizontal bars ----
const hbars = (items, color) => {
  const max = Math.max(1, ...items.map(i => i.value));
  return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0">' + items.map(i => {
    const w = Math.max(2, Math.round(i.value / max * 100));
    return '<tr><td style="padding:6px 0 2px;font-size:13px;color:' + INK + '">' + esc(i.label) + '</td><td align="right" style="padding:6px 0 2px;font-size:12px;color:' + MUTED + '">' + esc(i.text) + '</td></tr>' +
      '<tr><td colspan="2" style="padding:0 0 4px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" bgcolor="#f1f5f9"><tr><td width="' + w + '%" height="10" bgcolor="' + color + '" style="height:10px;line-height:10px;font-size:0">&nbsp;</td><td style="font-size:0">&nbsp;</td></tr></table></td></tr>';
  }).join('') + '</table>';
};
const products = (d.topProducts || []).map(p => ({ label: p.product, value: p.revenue, text: currency + ' ' + fmt(p.revenue) + ' - ' + fmt(p.quantitySold) + ' units' }));
const catTotal = (d.categories || []).reduce((s, c) => s + c.revenue, 0) || 1;
const categories = (d.categories || []).map(c => ({ label: c.category, value: c.revenue, text: currency + ' ' + fmt(c.revenue) + ' - ' + Math.round(c.revenue / catTotal * 100) + '%' }));

// ---- highlights from the numbers (always present, even if the AI step returns nothing) ----
const hl = [];
hl.push('Revenue was ' + currency + ' ' + fmt(cur.revenue) + (d.revenueChangePct == null ? '.' : ', ' + (d.revenueChangePct < 0 ? 'down ' : 'up ') + Math.abs(d.revenueChangePct) + '% on last week (' + currency + ' ' + fmt(prev.revenue) + ').'));
const active = days.filter(x => x.revenue > 0);
if (active.length) {
  const best = active.reduce((a, b) => b.revenue > a.revenue ? b : a), worst = active.reduce((a, b) => b.revenue < a.revenue ? b : a);
  hl.push('Best day: ' + dayLabel(best.date) + ' (' + currency + ' ' + fmt(best.revenue) + '). Quietest day with sales: ' + dayLabel(worst.date) + ' (' + currency + ' ' + fmt(worst.revenue) + ').');
}
if ((d.topProducts || []).length && cur.revenue > 0) hl.push(d.topProducts[0].product + ' was the top product with ' + Math.round(d.topProducts[0].revenue / cur.revenue * 100) + '% of revenue.');
if ((d.categories || []).length) hl.push('Biggest category: ' + d.categories[0].category + ' (' + Math.round(d.categories[0].revenue / catTotal * 100) + '% of revenue).');
const highlights = '<ul style="margin:0;padding-left:18px;font-size:14px;line-height:1.6;color:' + INK + '">' + hl.map(h => '<li>' + esc(h) + '</li>').join('') + '</ul>';

// ---- written analysis from Gemini ----
const g = $input.first().json;
let ai = ((g.candidates && g.candidates[0] && g.candidates[0].content && g.candidates[0].content.parts) || []).map(p => p.text || '').join('');
ai = ai.replace(/^\s*```(?:html)?\s*/i, '').replace(/\s*```\s*$/, '').replace(/<\/?(html|head|body)[^>]*>/gi, '').replace(/<script[\s\S]*?<\/script>/gi, '').replace(/<style[\s\S]*?<\/style>/gi, '').trim();
if (!ai) ai = '<p style="color:' + MUTED + '">The written analysis was not available this week. The charts and highlights above are based on your sales data.</p>';

const section = (title, body) => '<tr><td style="padding:16px 24px 4px"><div style="font-size:15px;font-weight:bold;color:' + INK + ';padding-bottom:8px">' + title + '</div>' + body + '</td></tr>';
const rc = d.revenueChangePct;
const isAlert = rc != null && rc < -20;
const stripe = rc == null ? '#94a3b8' : (isAlert ? RED : (rc < 0 ? AMBER : GREEN));
const headline = d.revenueChangePct == null ? 'Weekly sales report' : (d.revenueChangePct < 0 ? 'Revenue down ' : 'Revenue up ') + Math.abs(d.revenueChangePct) + '%';

const html =
  '<div style="background:#f1f5f9;padding:16px 0;font-family:Arial,Helvetica,sans-serif">' +
  '<table role="presentation" width="640" align="center" cellpadding="0" cellspacing="0" style="max-width:100%;background:#ffffff;border-radius:8px">' +
  '<tr><td height="4" bgcolor="' + stripe + '" style="height:4px;font-size:0;line-height:4px">&nbsp;</td></tr>' +
  '<tr><td style="background:' + INK + ';padding:18px 24px"><div style="font-size:12px;color:#94a3b8;text-transform:uppercase">' + (isAlert ? 'Sales alert' : 'Weekly sales report') + '</div>' +
  '<div style="font-size:22px;font-weight:bold;color:#ffffff;padding:2px 0">' + esc(biz.businessName || 'Your business') + ': ' + headline + '</div>' +
  '<div style="font-size:12px;color:#94a3b8">' + dateLabel(cur.start) + ' to ' + dateLabel(cur.end) + ' (compared with the 7 days before)</div></td></tr>' +
  '<tr><td style="padding:16px 20px 0">' + kpis + '</td></tr>' +
  section('Revenue by day', dayChart) +
  section('Top products', hbars(products, INDIGO)) +
  (categories.length ? section('Revenue by category', hbars(categories, TEAL)) : '') +
  section('Highlights', highlights) +
  section(isAlert ? 'What happened and what to do' : 'Analysis', '<div style="font-size:14px;line-height:1.5;color:' + INK + '">' + ai + '</div>') +
  '<tr><td style="padding:16px 24px 20px;font-size:11px;color:' + MUTED + '">Generated automatically. Amounts are in ' + esc(currency) + ', after discounts.</td></tr>' +
  '</table></div>';

return [{ json: { html } }];
